  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2b;
      --panel-2: #17213a;
      --border: #24314e;
      --text: #e6edf7;
      --muted: #9fb0cc;
      --accent: #7c9cff;
      --accent-2: #56d6c7;
      --danger: #ff7b8a;
      --focus: rgba(124, 156, 255, 0.35);
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.16), transparent 35%),
        linear-gradient(180deg, #090d18 0%, #0b1020 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    .page-shell {
      width: min(100%, 720px);
      background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero {
      padding: 32px 32px 16px;
      background: linear-gradient(135deg, rgba(124, 156, 255, 0.14), rgba(86, 214, 199, 0.08));
      border-bottom: 1px solid rgba(255,255,255,0.06);
    }

    .hero h1 {
      margin: 0 0 10px;
      font-size: clamp(1.6rem, 2.2vw, 2.2rem);
      line-height: 1.1;
    }

    .hero p {
      margin: 0;
      color: var(--muted);
      max-width: 58ch;
    }

    .form-card {
      padding: 28px 32px 32px;
      background: rgba(10, 15, 28, 0.65);
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      letter-spacing: 0.01em;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      background: var(--panel);
      color: var(--text);
      border-radius: 14px;
      padding: 14px 16px;
      font-size: 1rem;
      outline: none;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    input::placeholder {
      color: #6f7f99;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px var(--focus);
      background: var(--panel-2);
    }

    .helper-text {
      color: var(--muted);
      font-size: 0.92rem;
    }

    .validation-message {
      min-height: 1.1em;
      color: var(--danger);
      font-size: 0.92rem;
    }

    .validation-message[data-visible="false"] {
      visibility: hidden;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      padding-top: 6px;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      font-weight: 700;
      color: #07111f;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(124, 156, 255, 0.22);
      transition: transform 140ms ease, filter 140ms ease;
    }

    button:hover { transform: translateY(-1px); filter: brightness(1.05); }
    button:active { transform: translateY(0); }

    .success-message {
      display: none;
      margin-top: 18px;
      padding: 14px 16px;
      border-radius: 14px;
      background: rgba(86, 214, 199, 0.12);
      border: 1px solid rgba(86, 214, 199, 0.24);
      color: #b9fff4;
    }

    .success-message[data-visible="true"] {
      display: block;
    }

    @media (max-width: 640px) {
      .hero, .form-card { padding-left: 18px; padding-right: 18px; }
      .actions { justify-content: stretch; }
      button { width: 100%; }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitted: false
    };

    const validators = {
      fullName(value) {
        if (!value.trim()) return "Full name is required.";
        return "";
      },
      email(value) {
        if (!value.trim()) return "Email address is required.";
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) return "Enter a valid email address.";
        return "";
      },
      phone(value) {
        if (!value.trim()) return "";
        if (!/^\+?[0-9\s()-]{7,20}$/.test(value.trim())) return "Enter a valid phone number or leave it blank.";
        return "";
      }
    };

    function Field({ id, label, type = "text", value, placeholder, helperText = "", required = false }) {
      const error = validators[id](value);
      const showError = state.touched[id] || state.submitted;
      const describedBy = [helperText ? `${id}-help` : "", `${id}-error`].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${id}">${label}${required ? " *" : ""}</label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            value="${escapeHtml(value)}"
            placeholder="${placeholder}"
            ${required ? "required" : ""}
            aria-describedby="${describedBy}"
            aria-invalid="${showError && error ? "true" : "false"}"
          />
          ${helperText ? `<div class="helper-text" id="${id}-help">${helperText}</div>` : ""}
          <div class="validation-message" id="${id}-error" data-visible="${showError && error ? "true" : "false"}">${showError ? escapeHtml(error) : ""}</div>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="page-shell" aria-labelledby="support-title">
          <header class="hero">
            <h1 id="support-title">Contact Support</h1>
            <p>Send us your details and we’ll get back to you as soon as possible.</p>
          </header>
          <div class="form-card">
            <form id="contact-form" novalidate>
              ${Field({
                id: "fullName",
                label: "Full name",
                value: state.values.fullName,
                placeholder: "Jordan Lee",
                required: true
              })}
              ${Field({
                id: "email",
                label: "Email address",
                type: "email",
                value: state.values.email,
                placeholder: "jordan@example.com",
                required: true
              })}
              ${Field({
                id: "phone",
                label: "Phone number",
                type: "tel",
                value: state.values.phone,
                placeholder: "+1 (555) 123-4567",
                helperText: "Optional. Use the format +1 (555) 123-4567 or a similar international phone number."
              })}
              <div class="actions">
                <button type="submit">Submit</button>
              </div>
              <div class="success-message" id="success-message" data-visible="false">Thanks — your message is ready to send.</div>
            </form>
          </div>
        </section>
      `;
    }

    function escapeHtml(text) {
      return String(text)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function validateAll() {
      return {
        fullName: validators.fullName(state.values.fullName),
        email: validators.email(state.values.email),
        phone: validators.phone(state.values.phone)
      };
    }

    function render() {
      document.getElementById("app").innerHTML = ContactForm();

      const form = document.getElementById("contact-form");
      const success = document.getElementById("success-message");
      const inputs = ["fullName", "email", "phone"];

      inputs.forEach((name) => {
        const input = document.getElementById(name);
        input.addEventListener("input", (event) => {
          state.values[name] = event.target.value;
          state.submitted = false;
          render();
        });
        input.addEventListener("blur", () => {
          state.touched[name] = true;
          render();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;
        const errors = validateAll();
        const hasErrors = Object.values(errors).some(Boolean);
        if (!hasErrors) {
          success.setAttribute("data-visible", "true");
        } else {
          success.setAttribute("data-visible", "false");
        }
        render();
      });
    }

    render();
  </script>
</body>
</html>
